import { useEffect, useEffectEvent } from 'react';

function Room({ roomId, theme }) {
  const onConnected = useEffectEvent(() => {
    logEvent('connected', roomId, theme); // всегда свежая theme
  });
  useEffect(() => {
    const conn = connect(roomId);
    onConnected();
    return () => conn.close();
  }, [roomId]); // theme тут нет
  return null;
}
